for index in pro['cohorts']['B']:
 f=paths.loc[paths.episode_index.eq(index)&paths.path.eq('free')].sort_values('step');r=paths.loc[paths.episode_index.eq(index)&paths.path.eq('recorded')].sort_values('step');final=f.iloc[-1];record=r.iloc[-1];x=(final[obs].to_numpy(float)-means)/scales;y=(record[obs].to_numpy(float)-means)/scales
 dist=((ref-x)*weights)**2;k=np.argpartition(dist.sum(axis=1),49)[49];comp=dist[k];record_same=((ref[k]-y)*weights)**2;change=comp-record_same;selection_delta=record_same.sum()-float(record.state_distance)**2
